<?php
declare(strict_types=1);
$root = __DIR__ . '/.voice-learning-sandbox'; @mkdir($root); @mkdir($root . '/includes'); @mkdir($root . '/storage');
copy(__DIR__ . '/../../functions.php', $root . '/functions.php');
foreach (['invoice_voice_learning.php','invoice_catalog.php','logger.php','email_transport.php'] as $f) copy(__DIR__ . '/../../includes/' . $f, $root . '/includes/' . $f);
file_put_contents($root . '/storage/.htaccess', "Require all denied\n");
require $root . '/functions.php'; require $root . '/includes/invoice_catalog.php'; require $root . '/includes/invoice_voice_learning.php';
$n=0; $assert=static function(bool $ok,string $message)use(&$n):void{$n++;if(!$ok)throw new RuntimeException($message);};
$a=str_repeat('a',32); $b=str_repeat('b',32);
$assert(portal_voice_learning_path('central-admin') === null && portal_voice_learning_path('../x') === null, 'Only personal IDs are allowed');
$assert(portal_voice_learning_read($a)['learning'] === false, 'Learning is opt-in');
$legacy=portal_voice_learning_empty(); unset($legacy['numeric_learning'], $legacy['numeric_corrections']); save_data(portal_voice_learning_path($b), $legacy);
$assert(portal_voice_learning_read($b)['numeric_learning'] === false && portal_voice_learning_read($b)['numeric_corrections'] === [], 'Existing profiles migrate with numeric learning disabled');
$assert(!(portal_voice_learning_update($b,'numeric_on',[])['ok']), 'Numeric opt-in requires learning to be enabled');
$assert(!(portal_voice_learning_update($a, 'auto_on', [])['ok']), 'Automatic mode requires opt-in and 50');
$assert(portal_voice_learning_update($a, 'start', [])['ok'], 'Start learning');
$obs=str_repeat('1',32);
$data=['observation_id'=>$obs, 'heard'=>'Glasparation', 'approved'=>'Glasreparation'];
$assert(portal_voice_learning_update($a, 'review', $data)['profile']['reviewed'] === 1, 'A manual review counts');
$assert(portal_voice_learning_update($a, 'review', $data)['profile']['reviewed'] === 1, 'Duplicate observation cannot count twice');
$assert(portal_voice_learning_read($b)['reviewed'] === 0 && portal_voice_learning_read($b)['corrections'] === [], 'Profiles are separate');
$assert(!portal_voice_learning_update($b,'dictionary_update',['heard'=>'Glasparation','old_approved'=>'Glasreparation','approved'=>'Nytt'])['ok'], 'A different profile cannot modify a correction');
$assert(!portal_voice_learning_update($a,'dictionary_update',['heard'=>'Glasparation','old_approved'=>'Gammalt','approved'=>'Nytt'])['ok'], 'Stale dictionary edits rejected');
$assert(!portal_voice_learning_update($a,'dictionary_update',['heard'=>'Glasparation','old_approved'=>'Glasreparation','approved'=>"bad\nvalue"])['ok'], 'Dictionary text validated');
$change=portal_voice_learning_update($a,'dictionary_update',['heard'=>'Glasparation','old_approved'=>'Glasreparation','approved'=>'Rättat']);
$assert($change['ok'] && $change['profile']['reviewed'] === 1 && $change['profile']['corrections'][0]['approved']==='Rättat', 'Manual edit does not count as recognition');
$assert(!portal_voice_learning_update($a,'dictionary_delete',['heard'=>'Glasparation','old_approved'=>'Glasreparation'])['ok'], 'Old form cannot delete an updated mapping');
$assert(portal_voice_learning_update($a,'dictionary_update',['heard'=>'Glasparation','old_approved'=>'Rättat','approved'=>'Glasreparation'])['ok'], 'Restore for other tests');
$assert(!(portal_voice_learning_update($a, 'auto_on', [])['ok']), 'One review is not enough');
for ($i=2; $i<=50; $i++) portal_voice_learning_update($a, 'review', ['observation_id'=>str_pad(dechex($i),32,'0',STR_PAD_LEFT),'heard'=>'','approved'=>'Arbete']);
$assert(portal_voice_learning_read($a)['reviewed'] === 50, '50 distinct reviewed observations');
$assert(portal_voice_learning_update($a, 'auto_on', [])['profile']['auto'] === true, 'Auto requires explicit enable after 50');
$tracked=portal_voice_learning_update($a, 'track_auto', ['heard'=>'Sten skott', 'approved'=>'Sten skott', 'numeric_qty'=>'2', 'numeric_price'=>'999.25', 'numeric_unit'=>'st']);
$token=$tracked['token'] ?? '';
$assert($tracked['ok'] && is_string($token) && !str_contains($token, 'Sten'), 'Automatic rows get an opaque encrypted token');
$assert(portal_voice_learning_open($a, portal_voice_learning_read($a)['provenance_key'], $token)['heard'] === 'Sten skott', 'Owner can recover original description');
$assert(portal_voice_learning_open($a, portal_voice_learning_read($a)['provenance_key'], $token)['numeric'] === null, 'Opted-out profiles ignore numeric inputs in tracking');
$assert(portal_voice_learning_open($b, portal_voice_learning_read($a)['provenance_key'], $token) === null, 'Another user cannot use a token');
$assert(portal_voice_learning_open($a, portal_voice_learning_read($a)['provenance_key'], substr($token,0,-1) . '*') === null, 'Tampering is rejected');
$synced=portal_voice_learning_update($a, 'sync_auto', ['voice_token'=>$token,'approved'=>'Stenskott']);
$assert($synced['ok'] && $synced['profile']['reviewed'] === 50 && count($synced['profile']['corrections']) === 2, 'Later edit trains without increasing manual review count');
$token=$synced['token'];
$nochange=portal_voice_learning_update($a, 'sync_auto', ['voice_token'=>$token,'approved'=>'Stenskott']);
$assert($nochange['ok'] && $nochange['token'] === $token, 'Unchanged re-opened rows do not create feedback');
$assert(!(portal_voice_learning_update($b, 'sync_auto', ['voice_token'=>$token,'approved'=>'Fel'])['ok']), 'Foreign account cannot update profile via token');
$assert(portal_voice_learning_read($a)['numeric_learning'] === false, 'Numeric learning is separately opted out by default');
$assert(portal_voice_learning_update($a, 'numeric_on', [])['profile']['numeric_learning'] === true, 'Numeric learning requires explicit opt-in');
$assert(portal_voice_learning_number('2,50', 'qty') === '2.5' && portal_voice_learning_number('0', 'price') === '0' && portal_voice_learning_number('-1', 'price') === null && portal_voice_learning_number('10000001', 'price') === null, 'Numeric input is canonical and range checked');
$numericTrack=portal_voice_learning_update($a, 'track_auto', ['heard'=>'Glasbyte','approved'=>'Glasbyte','numeric_qty'=>'2','numeric_price'=>'750','numeric_unit'=>'st']);
$assert($numericTrack['ok'] && !str_contains($numericTrack['token'], '750'), 'Numeric provenance is encrypted');
$numericToken=$numericTrack['token'];
$sharedItem=['art'=>'Glasbyte','unit'=>'st','qty'=>2.0,'price'=>750.0,'voice_token'=>$numericToken];
$oldInvoice=['items'=>[$sharedItem]];
$assert(isset(portal_voice_learning_filter_shared_tokens([$sharedItem],$oldInvoice,$b)[0]['voice_token']), 'Another account preserves an unchanged shared link');
$modified=$sharedItem; $modified['price']=800.0;
$assert(!isset(portal_voice_learning_filter_shared_tokens([$modified],$oldInvoice,$b)[0]['voice_token']), 'Other accounts cannot attribute their price edits to the speaker even via a crafted save');
$assert(isset(portal_voice_learning_filter_shared_tokens([$modified],$oldInvoice,$a)[0]['voice_token']), 'The speaker keeps provenance when editing their own row');
$numericSync=portal_voice_learning_update($a, 'sync_auto', ['voice_token'=>$numericToken,'approved'=>'Glasbyte','numeric_qty'=>'3','numeric_price'=>'800','numeric_unit'=>'st']);
$numeric=$numericSync['profile']['numeric_corrections'];
$assert(count($numeric) === 2 && $numeric[0] === ['heard'=>'Glasbyte','unit'=>'st','field'=>'qty','from'=>'2','to'=>'3'] && $numeric[1]['to'] === '800', 'Corrected numbers are recorded only as context-bound examples');
$assert($numericSync['profile']['reviewed'] === 50, 'Corrected automatic rows never increment review count');
$numericToken=$numericSync['token'];
$unchanged=portal_voice_learning_update($a, 'sync_auto', ['voice_token'=>$numericToken,'approved'=>'Glasbyte','numeric_qty'=>'3','numeric_price'=>'800','numeric_unit'=>'st']);
$assert($unchanged['token'] === $numericToken && count($unchanged['profile']['numeric_corrections']) === 2, 'Reloading unchanged numbers is not feedback');
$revert=portal_voice_learning_update($a, 'sync_auto', ['voice_token'=>$numericToken,'approved'=>'Glasbyte','numeric_qty'=>'2','numeric_price'=>'750','numeric_unit'=>'st']);
$assert($revert['profile']['numeric_corrections'] === [], 'Changing back removes the numeric suggestion');
$numericToken=$revert['token'];
$changedUnit=portal_voice_learning_update($a, 'sync_auto', ['voice_token'=>$numericToken,'approved'=>'Glasbyte','numeric_qty'=>'4','numeric_price'=>'900','numeric_unit'=>'tim']);
$assert($changedUnit['profile']['numeric_corrections'] === [] && portal_voice_learning_open($a,portal_voice_learning_read($a)['provenance_key'],$changedUnit['token'])['numeric'] === null, 'Changed units detach numeric provenance rather than mislearn');
$manual=portal_voice_learning_update($a, 'review', ['observation_id'=>str_repeat('f',32),'heard'=>'Arbete','approved'=>'Arbete','from_qty'=>'1','to_qty'=>'2','from_price'=>'500','to_price'=>'650','numeric_unit'=>'tim','approved_unit'=>'tim']);
$assert(count($manual['profile']['numeric_corrections']) === 2, 'Manual review also learns explicitly corrected numbers');
$assert(portal_voice_learning_update($a, 'numeric_off', [])['profile']['numeric_learning'] === false, 'Numeric learning can be paused independently');
$assert(portal_voice_learning_read($a)['numeric_corrections'] !== [], 'Pause keeps data until forgetting the profile');
$pausedSync=portal_voice_learning_update($a, 'sync_auto', ['voice_token'=>$numericToken,'approved'=>'Glasbyte','numeric_qty'=>'9','numeric_price'=>'999','numeric_unit'=>'st']);
$assert($pausedSync['ok'] && portal_voice_learning_open($a, portal_voice_learning_read($a)['provenance_key'], $pausedSync['token'])['numeric'] === null && count($pausedSync['profile']['numeric_corrections']) === 2, 'Edits while numeric learning is paused detach numeric provenance without learning');
$updated=portal_voice_learning_update($a, 'correction', ['heard'=>'Reparationn', 'approved'=>'Reparation']);
$assert($updated['ok'] && $updated['profile']['reviewed'] === 50 && count($updated['profile']['corrections']) === 3, 'Learning continues after automatic entry without counting it as review');
$updated=portal_voice_learning_update($a, 'correction', ['heard'=>'Reparationn', 'approved'=>'Reparationn']);
$assert(count($updated['profile']['corrections']) === 2, 'Correcting back removes a mapping');
$assert(!str_contains(file_get_contents(portal_voice_learning_path($a)), '999.25'), 'Unobserved prices are not persisted');
$assert(portal_voice_learning_update($a, 'pause', [])['profile']['auto'] === false, 'Pause disables auto');
$assert(!(portal_voice_learning_update($a, 'correction', ['heard'=>'A','approved'=>'B'])['ok']), 'Disabled learning cannot be updated');
$assert(portal_voice_learning_update($a,'dictionary_delete',['heard'=>'Glasparation','old_approved'=>'Glasreparation'])['ok'], 'Owner can remove a correction even when learning is paused');
$assert(portal_voice_learning_update($a, 'forget', [])['profile']['reviewed'] === 0, 'Forget resets profile');
portal_voice_learning_update($a, 'start', []);
$assert(!(portal_voice_learning_update($a, 'sync_auto', ['voice_token'=>$token,'approved'=>'Nytt'])['ok']), 'Forget destroys the key to old tokens');
file_put_contents(portal_voice_learning_path($a), '{bad');
$assert(portal_voice_learning_read($a) === null && !(portal_voice_learning_update($a,'start',[])['ok']), 'Corruption fails closed and is not overwritten');
$assert(file_get_contents(portal_voice_learning_path($a)) === '{bad', 'Corruption retained for recovery');
foreach (glob($root . '/storage/*') ?: [] as $f) unlink($f); unlink($root . '/storage/.htaccess'); rmdir($root . '/storage');
foreach (glob($root . '/includes/*') ?: [] as $f) unlink($f); rmdir($root . '/includes'); unlink($root . '/functions.php'); rmdir($root);
echo "PASS: $n personal voice learning checks.\n";
